function track(event, props) {
	if (typeof window === "undefined") return;
	try {
		const w = window;
		if (Array.isArray(w.dataLayer)) w.dataLayer.push({
			event,
			...props ?? {}
		});
		if (typeof w.gtag === "function") w.gtag("event", event, props ?? {});
	} catch {}
}
